// Call offer-service nie ustawia Content-Disposition, a URL /render nie ma
// nazwy pliku - n8n zapisuje binarke bez fileName/rozszerzenia. Ustawiamy je
// tu recznie, biorac rozszerzenie z szablonu (file[0].title), zeby wgrany
// plik mial to samo rozszerzenie co szablon (pptx/docx), nie zadne.
const offerRow = $('Button: Generate offer').first().json.body.data.rows[0];
const templateFile = ($('Get offer template').first().json.file || [])[0];
const nameOrUrl = templateFile?.title || templateFile?.url || '';
const ext = (nameOrUrl.split('.').pop() || 'pptx').toLowerCase();
const safeTitle = (offerRow.title || `offer-${offerRow.Id}`).replace(/[^\w\-. ]+/g, '_');
const fileName = `${safeTitle}.${ext}`;

const items = $input.all();
for (const item of items) {
  if (item.binary?.offer) {
    item.binary.offer.fileName = fileName;
  }
}
return items;
